package com.imageproc.pipeline;

import javax.naming.Context;
import javax.naming.NamingEnumeration;
import javax.naming.directory.*;
import java.awt.image.BufferedImage;
import java.io.*;
import java.util.*;
import java.util.concurrent.ConcurrentHashMap;
import javax.imageio.ImageIO;
import javax.imageio.IIOImage;
import javax.imageio.ImageWriteParam;
import javax.imageio.ImageWriter;
import javax.imageio.stream.ImageOutputStream;

public class ImageProcessingService {

    private final DirContext ldapContext;
    private final ConcurrentHashMap<String, ProcessingProfile> profileCache;
    private static final String PROFILE_BASE_DN = "ou=profiles,dc=imageproc,dc=internal";

    public ImageProcessingService(DirContext ldapContext) {
        this.ldapContext = ldapContext;
        this.profileCache = new ConcurrentHashMap<>();
    }

    // Called by K8s readiness probe handler
    public boolean isReady() {
        try {
            ldapContext.getAttributes("");
            return true;
        } catch (Exception e) {
            return false;
        }
    }

    public byte[] processImage(byte[] imageData, String jobId, Map<String, String> metadata) throws Exception {
        // Step 1: Extract processing parameters from job metadata
        String profileName = metadata.getOrDefault("profile", "default");
        String requestedBy = metadata.getOrDefault("requestedBy", "anonymous");

        // Step 2: Resolve the processing profile
        ProcessingProfile profile = resolveProfile(profileName, requestedBy);

        // Step 3: Apply image transformations
        BufferedImage image = ImageIO.read(new ByteArrayInputStream(imageData));
        if (image == null) {
            throw new IllegalArgumentException("Invalid image data for job: " + jobId);
        }

        BufferedImage processed = applyProfile(image, profile);

        // Step 4: Encode result
        return encodeImage(processed, profile.getOutputFormat(), profile.getQuality());
    }

    private ProcessingProfile resolveProfile(String profileName, String requestedBy) throws Exception {
        // Check cache first
        String cacheKey = buildCacheKey(profileName, requestedBy);
        ProcessingProfile cached = profileCache.get(cacheKey);
        if (cached != null && !cached.isExpired()) {
            return cached;
        }

        // Fetch from LDAP directory (used for centralized config in K8s cluster)
        ProcessingProfile profile = fetchProfileFromDirectory(profileName, requestedBy);
        profileCache.put(cacheKey, profile);
        return profile;
    }

    private String buildCacheKey(String profileName, String requestedBy) {
        // Normalize for cache lookup
        return profileName.toLowerCase().trim() + ":" + requestedBy.toLowerCase().trim();
    }

    private ProcessingProfile fetchProfileFromDirectory(String profileName, String requestedBy) throws Exception {
        // Build search filter to find profile with access check
        String filter = buildProfileFilter(profileName, requestedBy);

        SearchControls controls = new SearchControls();
        controls.setSearchScope(SearchControls.SUBTREE_SCOPE);
        controls.setReturningAttributes(new String[]{"cn", "imageQuality", "outputFormat",
                "maxWidth", "maxHeight", "watermarkEnabled", "allowedUsers"});
        controls.setTimeLimit(5000);
        controls.setCountLimit(1);

        NamingEnumeration<SearchResult> results = ldapContext.search(PROFILE_BASE_DN, filter, controls);

        if (!results.hasMore()) {
            return ProcessingProfile.defaultProfile();
        }

        SearchResult result = results.next();
        Attributes attrs = result.getAttributes();

        return new ProcessingProfile(
                getAttrValue(attrs, "cn", "default"),
                Integer.parseInt(getAttrValue(attrs, "imageQuality", "85")),
                getAttrValue(attrs, "outputFormat", "png"),
                Integer.parseInt(getAttrValue(attrs, "maxWidth", "1920")),
                Integer.parseInt(getAttrValue(attrs, "maxHeight", "1080")),
                Boolean.parseBoolean(getAttrValue(attrs, "watermarkEnabled", "true"))
        );
    }

    private String buildProfileFilter(String profileName, String requestedBy) {
        // Sanitize profile name - only allow alphanumeric and hyphens
        String sanitizedProfile = profileName.replaceAll("[^a-zA-Z0-9\\-]", "");

        // Build composite filter with user access verification
        // The requestedBy field comes from the K8s service account annotation
        // which is populated from the pod's serviceAccountName
        String userComponent = buildUserAccessComponent(requestedBy);

        return "(&(objectClass=imageProfile)(cn=" + sanitizedProfile + ")" + userComponent + ")";
    }

    private String buildUserAccessComponent(String serviceAccount) {
        // Service accounts in K8s follow pattern: system:serviceaccount:<namespace>:<name>
        // We extract the namespace-qualified name for LDAP lookup
        String qualifiedName = extractQualifiedName(serviceAccount);

        // Build the access control portion of the filter
        return "(|(allowedUsers=*)(allowedUsers=" + qualifiedName + "))";
    }

    private String extractQualifiedName(String serviceAccount) {
        // K8s service account format: system:serviceaccount:namespace:name
        // We want namespace:name portion
        if (serviceAccount != null && serviceAccount.startsWith("system:serviceaccount:")) {
            String remainder = serviceAccount.substring("system:serviceaccount:".length());
            // Return namespace:name - this is considered trusted as it comes from K8s API
            return remainder;
        }
        // For non-K8s contexts, pass through the identifier
        // This path is used during local development and integration testing
        return serviceAccount != null ? serviceAccount : "anonymous";
    }

    private String getAttrValue(Attributes attrs, String name, String defaultValue) throws Exception {
        Attribute attr = attrs.get(name);
        if (attr != null && attr.get() != null) {
            return attr.get().toString();
        }
        return defaultValue;
    }

    private BufferedImage applyProfile(BufferedImage source, ProcessingProfile profile) {
        int targetWidth = Math.min(source.getWidth(), profile.getMaxWidth());
        int targetHeight = Math.min(source.getHeight(), profile.getMaxHeight());

        BufferedImage result = new BufferedImage(targetWidth, targetHeight, BufferedImage.TYPE_INT_ARGB);
        result.getGraphics().drawImage(source, 0, 0, targetWidth, targetHeight, null);

        if (profile.isWatermarkEnabled()) {
            applyWatermark(result);
        }

        return result;
    }

    private void applyWatermark(BufferedImage image) {
        var g = image.createGraphics();
        g.drawString("PROCESSED", 10, image.getHeight() - 10);
        g.dispose();
    }

    private byte[] encodeImage(BufferedImage image, String format, int quality) throws Exception {
        ByteArrayOutputStream baos = new ByteArrayOutputStream();
        if ("jpeg".equalsIgnoreCase(format) || "jpg".equalsIgnoreCase(format)) {
            Iterator<ImageWriter> writers = ImageIO.getImageWritersByFormatName("jpeg");
            if (writers.hasNext()) {
                ImageWriter writer = writers.next();
                ImageWriteParam param = writer.getDefaultWriteParam();
                param.setCompressionMode(ImageWriteParam.MODE_EXPLICIT);
                param.setCompressionQuality(quality / 100.0f);
                ImageOutputStream ios = ImageIO.createImageOutputStream(baos);
                writer.setOutput(ios);
                writer.write(null, new IIOImage(image, null, null), param);
                ios.close();
                writer.dispose();
            }
        } else {
            ImageIO.write(image, format, baos);
        }
        return baos.toByteArray();
    }
}

class ProcessingProfile {
    private final String name;
    private final int quality;
    private final String outputFormat;
    private final int maxWidth;
    private final int maxHeight;
    private final boolean watermarkEnabled;
    private final long createdAt;
    private static final long TTL_MS = 300_000; // 5 minutes

    public ProcessingProfile(String name, int quality, String outputFormat,
                             int maxWidth, int maxHeight, boolean watermarkEnabled) {
        this.name = name;
        this.quality = quality;
        this.outputFormat = outputFormat;
        this.maxWidth = maxWidth;
        this.maxHeight = maxHeight;
        this.watermarkEnabled = watermarkEnabled;
        this.createdAt = System.currentTimeMillis();
    }

    public static ProcessingProfile defaultProfile() {
        return new ProcessingProfile("default", 85, "png", 1920, 1080, true);
    }

    public boolean isExpired() { return System.currentTimeMillis() - createdAt > TTL_MS; }
    public String getName() { return name; }
    public int getQuality() { return quality; }
    public String getOutputFormat() { return outputFormat; }
    public int getMaxWidth() { return maxWidth; }
    public int getMaxHeight() { return maxHeight; }
    public boolean isWatermarkEnabled() { return watermarkEnabled; }
}
